mapper.select:
select type, id, title, hits, menu_id, menu_name, detail_url from ( select 'menu' as type, m.id as id, m.class_name as title, m.hits as hits, m.id as menu_id, m.class_name as menu_name, '' as detail_url from t_oneshot m where m.is_deleted = 0 and m.hits > 0
and m.site_project_id = #{siteId}
union all
select 'content' as type, c.id as id, c.title as title, c.hits as hits, c.class_id as menu_id, o.class_name as menu_name, replace(replace(o.detail_page_url, '{id}', c.id), '{classId}', o.id) as detail_url from t_contents c inner join t_oneshot o on o.id = c.class_id where o.page_type = 1 and o.is_deleted = 0 and (o.detail_page_url != '' or o.detail_page_url is not null) and c.deleted = 0 and c.status = 1 and c.hits > 0
and o.site_project_id = #{siteId}
) t order by t.hits desc, t.id desc limit 10

